    if start == goal:
        return [start]

    directions = [(-1, 0), (0, 1), (1, 0), (0, -1)]
    stack = [start]
    visited = set([start])
    parent = {}

    goal_reached = False

    while stack:
        current = stack.pop()
        if current == goal:
            goal_reached = True
            break
        for dr, dc in directions:
            new_r = current[0] + dr
            new_c = current[1] + dc
            if is_out_of_bounds(new_r, new_c):
                continue
            if grid[new_r][new_c] == '#':
                continue
            if (new_r, new_c) in visited:
                continue
            visited.add((new_r, new_c))
            parent[(new_r, new_c)] = current
            stack.append((new_r, new_c))

    if goal_reached:
        path = []
        current = goal
        while current != start:
            path.append(current)
            current = parent[current]
        path.append(start)
        path.reverse()
        return path
    else:
        return []
